#!/bin/bash
# 0086 Studios: v24 homepage deploy (repo andai007/0086-site@4ea4f55)
set -euo pipefail
W=${W:-/www/wwwroot/0086studios.xyz}; R=${R:-/root}; C=4ea4f55; TS=$(date +%Y%m%d-%H%M%S)
B=$R/backup-0086-$TS; S=$R/stage-0086-$TS
[ -f "$W/index.html" ] || { echo "no $W/index.html"; exit 1; }
OWN=$(stat -c %U:%G "$W/index.html")
mkdir -p "$B-files" "$S/assets"
echo "== 1/4 backup (media excluded) -> $B.tar.gz"
tar czf "$B.tar.gz" -C "$W" --exclude='*.mp4' --exclude='*.MP4' --exclude='*.mov' --exclude='*.MOV' --exclude='*.webm' --exclude='*.m4v' --exclude='*.webp' --exclude='*.jpg' --exclude='*.JPG' --exclude='*.jpeg' --exclude='*.png' --exclude='*.PNG' --exclude='*.gif' --exclude='*.mp3' --exclude='*.wav' --exclude='*.zip' --exclude='*.psd' --exclude='*.pdf' . || [ $? -eq 1 ]
cp -a "$W/index.html" "$B-files/index-old-$TS.html"
cat > "$S/LIST" <<'L'
5678f636cac52d20265cedd238044c15b22f890749a5261b24c13ace5204c783 force preview-0086-source.html
da00dfa98164c718e7c0d581305fdee8189652b9774c144ce9eb1a091eddf334 force assets/preview-catalogue-v10.json
cb2a03e68269d1367e4fb7b59d24cbb89e146cfac99f026bbb564fda8f1dba4e force assets/preview-catalogue-v10.css
d1c8035d02c2b6e25a3c700d5bfad8f6d5e3eeaee8cfe2c3648ca46f8b71d286 force assets/preview-0086-layout-v4.css
9986d28d3d42281a7edb631de3bf7e085537ea8bab528367c0188dd29e89624e force assets/preview-0086-light-v6.css
5ca5d8a0b2e316f446d3239b73efbccb5e1e0ce0de2760dbb76a532b886498e0 force assets/preview-0086-field-v24.js
b9ae290a7b142bce1fe9d061af94109eed1e8d5fd65ca33e12481248e118c5cc force assets/preview-0086-music-v7.js
13bf1872a3653c346d2f9539bab541a7efa58b0090e084d04e92f9341b6c6030 keep assets/0086-logo.png
5e771bbe50999aa9bc5de6daa59446da547e9ecf83c933c809616550fd25f965 keep assets/external-media-config.js
L
echo "== 2/4 fetch + sha256 verify -> $S"
echo '' | base64 -d | gunzip > "$S/index.html"
echo "5176e24684d5327257ad76b13077bc56c3d9a8d7c2324856d793503e0fa0a792  $S/index.html" | sha256sum -c --quiet
get(){ for u in "https://raw.githubusercontent.com/andai007/0086-site/$C/$1" "https://cdn.jsdelivr.net/gh/andai007/0086-site@$C/$1" "https://andai007.github.io/0086-site/$1"; do
  if curl -fsSL --connect-timeout 8 --max-time 60 -o "$S/$1" "$u" && echo "$2  $S/$1" | sha256sum -c --quiet 2>/dev/null; then echo "ok $1 <- ${u%%/andai007*}"; return 0; fi; done
  echo "FAILED $1"; return 1; }
while read -r h m f; do get "$f" "$h"; done < "$S/LIST"
echo "== 3/4 install (backup each overwritten file)"
: > "$B-files/ADDED.txt"
inst(){ f=$1; if [ -e "$W/$f" ]; then mkdir -p "$B-files/$(dirname "$f")"; cp -a "$W/$f" "$B-files/$f"; else echo "$f" >> "$B-files/ADDED.txt"; fi
  mkdir -p "$W/$(dirname "$f")"; cp "$S/$f" "$W/$f.new-$TS"; chown "$OWN" "$W/$f.new-$TS"; chmod 644 "$W/$f.new-$TS"; mv -f "$W/$f.new-$TS" "$W/$f"; echo "installed $f"; }
while read -r h m f; do
  if [ "$m" = keep ] && [ -e "$W/$f" ]; then echo "kept existing $f"; else inst "$f"; fi
done < "$S/LIST"
inst index.html
cat > $R/rollback-0086-$TS.sh <<R
#!/bin/bash
set -e
W=$W; B=$B-files
cp -a "\$B/index-old-$TS.html" "\$W/index.html"
cd "\$B" && find . -type f ! -name ADDED.txt ! -name 'index-old-*' | while read -r f; do cp -a "\$f" "\$W/\$f"; done
while read -r f; do [ -n "\$f" ] && rm -f "\$W/\$f"; done < "\$B/ADDED.txt"
echo "rolled back to $TS"
R
chmod +x $R/rollback-0086-$TS.sh
echo "== 4/4 verify"
grep -q 0086-official-v24 "$W/index.html" && echo "marker in file OK"
curl -sk -o /dev/null -w "local https: %{http_code}\n" --resolve 0086studios.xyz:443:127.0.0.1 https://0086studios.xyz/ || true
curl -sk --resolve 0086studios.xyz:443:127.0.0.1 https://0086studios.xyz/ | grep -q 0086-official-v24 && echo "marker served OK" || echo "WARN marker not served (cache/CDN?)"
echo "DONE. backup: $B.tar.gz  $B-files/"
echo "ROLLBACK: bash $R/rollback-0086-$TS.sh"
